"""
pytest plugin for cocotb
"""
import os
import sys
import pytest
from pathlib import Path

def pytest_addoption(parser):
    """Add cocotb-specific options to pytest."""
    parser.addoption(
        "--simulator", 
        action="store", 
        default=os.environ.get("SIM", "verilator"),
        help="Simulator to use (verilator, icarus, etc.)"
    )
    parser.addoption(
        "--verilog-sources", 
        action="store",
        default=os.environ.get("VERILOG_SOURCES"),
        help="Verilog source files"
    )
    parser.addoption(
        "--top-module", 
        action="store",
        default=os.environ.get("TOPLEVEL"),
        help="Top-level module name"
    )
    parser.addoption(
        "--build-dir", 
        action="store",
        default="sim_build",
        help="Build directory"
    )

@pytest.hookimpl(tryfirst=True)
def pytest_configure(config):
    """Configure cocotb environment."""
    simulator = config.getoption("--simulator")
    if simulator:
        os.environ["SIM"] = simulator
    
    top_module = config.getoption("--top-module")
    if top_module:
        os.environ["TOPLEVEL"] = top_module
    
    verilog_sources = config.getoption("--verilog-sources")
    if verilog_sources:
        os.environ["VERILOG_SOURCES"] = verilog_sources
    
    os.environ["COCOTB_SIMULATOR"] = os.environ.get("SIM", "verilator")
    
    print(f"\n[cocotb] Simulator: {os.environ.get('SIM')}")
    print(f"[cocotb] Top module: {os.environ.get('TOPLEVEL')}")
    print(f"[cocotb] Verilog sources: {os.environ.get('VERILOG_SOURCES')}\n")

@pytest.fixture
def cocotb_test():
    """Fixture to mark cocotb tests."""
    return True

